  public static ProtobufTestValueProvider<?> forType(Type type) {
    switch (type) {
      case DOUBLE:
        return DOUBLE_PROVIDER;
      case FLOAT:
        return FLOAT_PROVIDER;
      case UINT32:
        return UINT32_PROVIDER;
      case INT32:
