public class ThenChainExample {
    public static void main(String[] args) {
        DeferredFactory factory = new DeferredFactory();
        Deferred<Integer> deferred = factory.defer();

        deferred.then(new Callbacks.SuccessCallback<Integer, String>() {
            @Override
            public String onSuccess(Integer result) {
                System.out.println("First then: " + result);
                return "Converted to string: " + result;
            }
        }).then(new Callbacks.SuccessCallback<String, VoidType>() {
            @Override
            public VoidType onSuccess(String result) {
                System.out.println("Second then: " + result);
                return VoidType.VOID;
            }
        }).fail(new FailureCallBack() {
            @Override
            public void onFail(Exception e) {
                System.err.println("Error occurred: " + e.getMessage());
            }
        });

        // Simulate async completion
        deferred.resolve(42);
    }
}

