import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

import java.io.IOException;

import org.json.JSONException;
import org.json.JSONObject;
import org.junit.Test;

import org.xlcloud.service.heat.parsers.ParserTestUtil;
import org.xlcloud.service.heat.template.fields.ConfigFields;
import org.xlcloud.service.heat.template.fields.MetadataFields;
import org.xlcloud.service.heat.template.resources.metadata.cfninit.FileConfiguration;
import org.xlcloud.service.heat.template.resources.metadata.cfninit.Files;

/**
 * @author Konrad Król, AMG.net
 */
public class FilesParserTest {

    private final static String RESOURCE_METADATA_TEMPLATE = "resources/resource-metadata.template";

    private FilesParser parser = new FilesParser();

    @Test
    public void testFromJSON() throws JSONException, IOException {
        Files files = parser.fromJSON(getTestJSON());
        FileConfiguration fileConfig = files.getFileConfiguration("/tmp/setup.mysql");

        assertNotNull(fileConfig);
        assertTrue(fileConfig.hasJsonContent());
        assertEquals("000644", fileConfig.getMode());
        assertEquals("root", fileConfig.getOwner());
        assertEquals("root", fileConfig.getGroup());

        FileConfiguration fileConfig2 = files.getFileConfiguration("/tmp/setup.mysql.log");
        assertNotNull(fileConfig2);
        assertEquals("done", fileConfig2.getContent());
    }


    private JSONObject getTestJSON() throws IOException, JSONException {
        return ParserTestUtil.getJSONFromFile(RESOURCE_METADATA_TEMPLATE).getJSONObject(MetadataFields.CFN_INIT.jsonKey()).getJSONObject("config").getJSONObject(ConfigFields.FILES.jsonKey());
    }
}

