private void updateHeaderScroll() {
        if (mHeader == null) return;

        final int scroll = mHeaderScroll;
        final float progress = mHeaderHeight == 0 ? 0 : (float) scroll / mHeaderHeight;

        // Update header translation
        mHeader.setTranslationY(-scroll);

        // Update background translation based on scroll mode
        if (mHeaderBackground != null) {
            switch (mHeaderBackgroundScrollMode) {
                case HEADER_BACKGROUND_SCROLL_PARALLAX:
                    mHeaderBackground.setTranslationY(-scroll / 2);
                    break;
                case HEADER_BACKGROUND_SCROLL_STATIC:
                    mHeaderBackground.setTranslationY(0);
                    break;
                default: // HEADER_BACKGROUND_SCROLL_NORMAL
                    mHeaderBackground.setTranslationY(-scroll);
                    break;
            }
        }

        // Update header header (title/shadows) alpha
        if (mHeaderHeader != null) {
            mHeaderHeader.setAlpha(1 - progress);
        }

        // Notify listener
        if (mOnHeaderScrollChangedListener != null) {
            mOnHeaderScrollChangedListener.onHeaderScrollChanged(progress, mHeaderHeight, scroll);
        }

