			return false;
		else if(!(user instanceof User))
			return false;
		else if(this==user)
			return true;
		else if(user.hashCode()!=this.hashCode())
			return false;
		else{
			if(((User)user).getUserName().equals(this.userName)
					&& ((User)user).getHostName().equals(this.hostName)){
				return true;
			}
			else{ 
